// ── Minimal hand-written lexer ───────────────────────────────────
function lex(source) {
  const tokens = [];
  let i = 0;
  while (i < source.length) {
    // skip whitespace
    if (/\s/.test(source[i])) { i++; continue; }
    // number literal
    if (/[0-9]/.test(source[i])) {
      let num = '';
      while (i < source.length && /[0-9]/.test(source[i])) num += source[i++];
      tokens.push({ type: 'NUMBER', value: Number(num) });
      continue;
    }
    // identifier or keyword
    if (/[a-zA-Z_]/.test(source[i])) {
      let word = '';
      while (i < source.length && /[\w]/.test(source[i])) word += source[i++];
      const KEYWORDS = new Set(['let', 'if', 'return']);
      tokens.push({ type: KEYWORDS.has(word) ? 'KEYWORD' : 'IDENT', value: word });
      continue;
    }
    // single-char operators and punctuation
    const SINGLE = { '+': 'PLUS', '-': 'MINUS', '*': 'STAR', '=': 'EQ', ';': 'SEMI' };
    if (SINGLE[source[i]]) {
      tokens.push({ type: SINGLE[source[i]], value: source[i] });
      i++;
      continue;
    }
    throw new SyntaxError(`Unexpected character: '${source[i]}' at position ${i}`);
  }
  tokens.push({ type: 'EOF', value: null });
  return tokens;
}

const tokens = lex('let total = 10 + 32;');
console.log(tokens.map(t => `${t.type}(${t.value})`).join(' '));
// KEYWORD(let) IDENT(total) EQ(=) NUMBER(10) PLUS(+) NUMBER(32) SEMI(;) EOF(null)

// ── Minimal recursive-descent parser (arithmetic expressions) ────
function parse(tokens) {
  let pos = 0;
  const peek = () => tokens[pos];
  const consume = (type) => {
    if (peek().type !== type) throw new SyntaxError(`Expected ${type}, got ${peek().type}`);
    return tokens[pos++];
  };

  // expression ::= term ((PLUS | MINUS) term)*
  function parseExpression() {
    let node = parseTerm();
    while (peek().type === 'PLUS' || peek().type === 'MINUS') {
      const op = consume(peek().type).value;
      node = { type: 'BinaryExpr', op, left: node, right: parseTerm() };
    }
    return node;
  }

  // term ::= NUMBER
  function parseTerm() {
    const tok = consume('NUMBER');
    return { type: 'Literal', value: tok.value };
  }

  return parseExpression();
}

// Lex just the arithmetic part: 10 + 32
const exprTokens = lex('10 + 32');
const ast = parse(exprTokens);
console.log(JSON.stringify(ast, null, 2));
// { type: 'BinaryExpr', op: '+',
//   left:  { type: 'Literal', value: 10 },
//   right: { type: 'Literal', value: 32 } }

// ── Evaluating the AST (interpreter) ────────────────────────────
function evaluate(node) {
  if (node.type === 'Literal') return node.value;
  if (node.type === 'BinaryExpr') {
    const l = evaluate(node.left);
    const r = evaluate(node.right);
    if (node.op === '+') return l + r;
    if (node.op === '-') return l - r;
    throw new Error(`Unknown operator: ${node.op}`);
  }
  throw new Error(`Unknown node type: ${node.type}`);
}

// Parse and evaluate '10 + 32'
const result = evaluate(ast);
console.log(result); // 42

// ── Summary of responsibilities ──────────────────────────────────
// Stage          | Input            | Output       | Errors
// -------------- | ---------------- | ------------ | ------
// Lexer          | char stream      | token stream | LexicalError
// Parser         | token stream     | AST          | SyntaxError
// Semantic Anal. | AST              | typed AST    | TypeError
// Code Gen/Eval  | AST              | output/exec  | RuntimeError

